<?php
declare(strict_types=1);requireRole('admin');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='officer-pools';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$errors){try{if($action==='assign-division'){$officer=filter_input(INPUT_POST,'officer_id',FILTER_VALIDATE_INT);$ds=filter_input(INPUT_POST,'ds_division_id',FILTER_VALIDATE_INT);if(!$officer||!$ds)throw new RuntimeException('Select an officer and DS Division.');$geo=database()->prepare('SELECT district_id FROM ds_divisions WHERE id=:id AND status="active"');$geo->execute(['id'=>$ds]);$district=$geo->fetchColumn();if(!$district)throw new RuntimeException('Selected division is unavailable.');$s=database()->prepare("UPDATE users SET ds_division_id=:ds,district_id=:district,division=(SELECT name FROM ds_divisions WHERE id=:ds2) WHERE id=:officer AND role='social-service-officer'");$s->execute(['ds'=>$ds,'district'=>$district,'ds2'=>$ds,'officer'=>$officer]);if(!$s->rowCount())throw new RuntimeException('Officer assignment was not changed.');logActivity('Officer Pools','Assigned Social Service Officer to a division','USR-'.$officer);$message='Officer division assigned.';}elseif($action==='allocate-stock'){$officer=filter_input(INPUT_POST,'officer_id',FILTER_VALIDATE_INT);$item=filter_input(INPUT_POST,'item_id',FILTER_VALIDATE_INT);$quantity=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);if(!$officer||!$item||!$quantity||$quantity<1)throw new RuntimeException('Select an officer, item, and valid quantity.');$db=database();$db->beginTransaction();$u=$db->prepare("SELECT ds_division_id FROM users WHERE id=:id AND role='social-service-officer' AND status='active' FOR UPDATE");$u->execute(['id'=>$officer]);$ds=$u->fetchColumn();if(!$ds)throw new RuntimeException('Officer must be assigned to a DS Division first.');$stock=$db->prepare('SELECT quantity FROM division_inventory WHERE ds_division_id=:ds AND item_id=:item FOR UPDATE');$stock->execute(['ds'=>$ds,'item'=>$item]);$available=(int)$stock->fetchColumn();if($available<$quantity)throw new RuntimeException("Insufficient division stock. Available: $available.");$db->prepare('UPDATE division_inventory SET quantity=quantity-:quantity WHERE ds_division_id=:ds AND item_id=:item')->execute(['quantity'=>$quantity,'ds'=>$ds,'item'=>$item]);$db->prepare('INSERT INTO officer_pools(officer_id,item_id,allocated) VALUES(:officer,:item,:quantity) ON DUPLICATE KEY UPDATE allocated=allocated+VALUES(allocated)')->execute(['officer'=>$officer,'item'=>$item,'quantity'=>$quantity]);$db->prepare('INSERT INTO pool_allocations(officer_id,item_id,quantity,allocated_by) VALUES(:officer,:item,:quantity,:admin)')->execute(['officer'=>$officer,'item'=>$item,'quantity'=>$quantity,'admin'=>$_SESSION['user_id']]);$db->commit();logActivity('Officer Pools',"Allocated $quantity item(s) to officer pool",'USR-'.$officer);$message='Stock allocated to officer pool.';}else throw new RuntimeException('Invalid pool action.');$_SESSION['flash_success']=$message;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=officer-pools');exit;}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to update officer pool.';}}}
try{$officers=database()->query("SELECT id,full_name,ds_division_id FROM users WHERE role='social-service-officer' AND status='active' ORDER BY full_name")->fetchAll();$divisions=database()->query("SELECT ds.id,CONCAT(d.name,' — ',ds.name) name FROM ds_divisions ds JOIN districts d ON d.id=ds.district_id WHERE ds.status='active' ORDER BY d.name,ds.name")->fetchAll();$divisionStock=database()->query('SELECT di.item_id,di.ds_division_id,di.quantity,i.item_name,i.variety,ds.name division_name FROM division_inventory di JOIN inventory_items i ON i.id=di.item_id JOIN ds_divisions ds ON ds.id=di.ds_division_id WHERE di.quantity>0 ORDER BY ds.name,i.item_name')->fetchAll();$rows=database()->query('SELECT u.full_name,ds.name ds_name,d.name district_name,i.item_name,i.variety,p.allocated,p.distributed,p.reused,(p.allocated-p.distributed+p.reused) remaining,u.status FROM officer_pools p JOIN users u ON u.id=p.officer_id LEFT JOIN ds_divisions ds ON ds.id=u.ds_division_id LEFT JOIN districts d ON d.id=u.district_id JOIN inventory_items i ON i.id=p.item_id ORDER BY u.full_name,i.item_name')->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$officers=$divisions=$divisionStock=$rows=[];$errors[]='Officer pools are unavailable.';}
$totals=['officers'=>count($officers),'allocated'=>array_sum(array_column($rows,'allocated')),'distributed'=>array_sum(array_column($rows,'distributed')),'remaining'=>array_sum(array_column($rows,'remaining'))];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Social Service Officer Pools | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/admin-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Social Service Officer Pools</h1></div></header><main class="dashboard-content officer-pools-workflow"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="operation-summary-grid"><?php foreach([['Total Officers',$totals['officers']],['Total Allocated',$totals['allocated']],['Total Distributed',$totals['distributed']],['Total Remaining',$totals['remaining']]] as [$label,$value]):?><article class="operation-summary-card"><span>&#128230;</span><p><?=$label?></p><strong><?=number_format((int)$value)?></strong><small>Live pool total</small></article><?php endforeach;?></section><section class="pool-admin-forms"><form method="post" class="admin-data-card compact-master-form"><h2>Assign Officer Division</h2><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="assign-division"><label>Officer<select name="officer_id" required><option value="">Select officer</option><?php foreach($officers as $o):?><option value="<?=(int)$o['id']?>"><?=htmlspecialchars($o['full_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>DS Division<select name="ds_division_id" required><option value="">Select division</option><?php foreach($divisions as $d):?><option value="<?=(int)$d['id']?>"><?=htmlspecialchars($d['name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><button class="admin-primary-action">Assign Division</button></form><form method="post" class="admin-data-card compact-master-form"><h2>Allocate Division Stock</h2><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="allocate-stock"><label>Officer<select name="officer_id" required><option value="">Select officer</option><?php foreach($officers as $o):?><option value="<?=(int)$o['id']?>"><?=htmlspecialchars($o['full_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Available Division Stock<select name="item_id" required><option value="">Select item</option><?php foreach($divisionStock as $s):?><option value="<?=(int)$s['item_id']?>"><?=htmlspecialchars($s['division_name'].' — '.$s['item_name'].($s['variety']?' / '.$s['variety']:'').' ('.$s['quantity'].')',ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="1" required></label><button class="admin-primary-action">Allocate to Pool</button></form></section><section class="admin-data-card pool-table-card"><div class="admin-data-header"><h2>Officer Pool Balances</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table officer-pools-table"><thead><tr><th>Officer</th><th>DS Division</th><th>District</th><th>Item</th><th>Allocated</th><th>Distributed</th><th>Reused</th><th>Remaining</th><th>Stock Level</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10" class="admin-empty-row">No officer pool allocations available.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars($r['ds_name']?:'Unassigned',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['district_name']?:'—',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?></td><td><?=(int)$r['allocated']?></td><td><?=(int)$r['distributed']?></td><td><?=(int)$r['reused']?></td><td><?=(int)$r['remaining']?></td><td><?=((int)$r['remaining']===0?'Empty':((int)$r['remaining']<5?'Low':'OK'))?></td><td><?=ucfirst($r['status'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
